/// An optional dependency's marker can be omitted from the lockfile when the extra is only active
/// in environments that satisfy the same marker. Ensure export restores the extra's activation
/// marker instead of making the dependency unconditional.
#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_conditional_transitive_extra() -> Result<()> {
    let server = PackseServer::new("packages/export-markers.toml");
    let context = uv_test::test_context!("3.12").with_default_index(&server.index_url());

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.10"
        dependencies = ["optional-parent==2.7.0"]

        [project.optional-dependencies]
        backport = ["optional-parent[backport]==2.7.0 ; python_full_version < '3.14'"]
        "#,
    )?;

    context.lock().assert().success();

    uv_snapshot!(context.filters(), context.export().arg("--all-extras").arg("--no-hashes"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --all-extras --no-hashes
    optional-backport==1.5.0 ; python_full_version < '3.14'
        # via optional-parent
    optional-parent==2.7.0
        # via project

    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    Ok(())
}

