#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_simplifies_selected_root_extra_markers_from_lock() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["typing-extensions ; extra == 'foo' or extra == 'bar'"]

        [project.optional-dependencies]
        foo = []
        bar = []
        "#,
    )?;

    let lock = context.temp_dir.child("uv.lock");
    lock.write_str(
        r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "typing-extensions", marker = "extra == 'foo' or extra == 'bar'" },
        ]

        [package.optional-dependencies]
        foo = []
        bar = []

        [package.metadata]
        requires-dist = [
            { name = "typing-extensions", marker = "extra == 'foo' or extra == 'bar'" },
        ]
        provides-extras = ["foo", "bar"]

        [[package]]
        name = "typing-extensions"
        version = "4.10.0"
        source = { registry = "https://pypi.org/simple" }
        dependencies = []
        "#,
    )?;

    uv_snapshot!(
        context.filters(),
        context
            .export()
            .arg("--all-extras")
            .arg("--frozen")
            .arg("--no-hashes"),
        @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --all-extras --frozen --no-hashes
    typing-extensions==4.10.0
        # via project
    "
    );

    Ok(())
}

#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_prune() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = [
            "jupyter-client"
        ]
    "#,
    )?;

    // project v0.1.0
    // └── jupyter-client v8.6.1
    //     ├── jupyter-core v5.7.2
    //     │   ├── platformdirs v4.2.0
    //     │   └── traitlets v5.14.2
    //     ├── python-dateutil v2.9.0.post0
    //     │   └── six v1.16.0
    //     ├── pyzmq v25.1.2
    //     ├── tornado v6.4
    //     └── traitlets v5.14.2

    uv_snapshot!(
        context.filters(),
        context.export()
            .arg("--no-hashes")
            .arg("--prune")
            .arg("jupyter-core"),
            @"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --no-hashes --prune jupyter-core
    cffi==1.16.0 ; implementation_name == 'pypy'
        # via pyzmq
    jupyter-client==8.6.1
        # via project
    pycparser==2.21 ; implementation_name == 'pypy'
        # via cffi
    python-dateutil==2.9.0.post0
        # via jupyter-client
    pyzmq==25.1.2
        # via jupyter-client
    six==1.17.0
        # via python-dateutil
    tornado==6.4
        # via jupyter-client
    traitlets==5.14.2
        # via jupyter-client

    ----- stderr -----
    Resolved 11 packages in [TIME]
    "
    );

    Ok(())
}

