#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_non_root() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0", "child"]

        [tool.uv.workspace]
        members = ["child"]

        [tool.uv.sources]
        child = { workspace = true }

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    let child = context.temp_dir.child("child");
    child.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "child"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["iniconfig>=2"]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    context.lock().assert().success();

    uv_snapshot!(context.filters(), context.export().arg("--package").arg("child"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --package child
    -e ./child
    iniconfig==2.0.0 \
        --hash=sha256:48c42a08c0ec1a24f2fe45f4efdefc9c19ac8e0aa8e82284503ccba80398bec3 \
        --hash=sha256:8a0fc44e516906bdecc91af1c3bc12134c9d1647a482446edc62f2f72191416c
        # via child

    ----- stderr -----
    Resolved 6 packages in [TIME]
    ");

    Ok(())
}

/// Regression test for <https://github.com/astral-sh/uv/issues/20912>.
/// Workspace-root groups are available to selected members, but defaults remain member-scoped.
#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_workspace_member_ignores_root_default_group() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    context
        .temp_dir
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "root"
            version = "0.1.0"
            requires-python = ">=3.12"

            [dependency-groups]
            dev = ["iniconfig"]

            [tool.uv.workspace]
            members = ["child"]
        "#})?;

    context
        .temp_dir
        .child("child")
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "child"
            version = "0.1.0"
            requires-python = ">=3.12"
            dependencies = ["typing-extensions"]
        "#})?;

    context.lock().assert().success();

    uv_snapshot!(context.filters(), context.export()
        .arg("--frozen")
        .arg("--no-header")
        .arg("--no-hashes")
        .arg("--no-annotate")
        .arg("--package").arg("child"), @"
    exit_code: 0 (success)
    ----- stdout -----
    typing-extensions==4.10.0
    ");

    uv_snapshot!(context.filters(), context.export()
        .arg("--no-header")
        .arg("--no-hashes")
        .arg("--no-annotate")
        .arg("--package").arg("child"), @"
    exit_code: 0 (success)
    ----- stdout -----
    typing-extensions==4.10.0

    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.export()
        .arg("--frozen")
        .arg("--no-header")
        .arg("--no-hashes")
        .arg("--no-annotate")
        .arg("--package").arg("child")
        .arg("--group").arg("dev"), @"
    exit_code: 0 (success)
    ----- stdout -----
    iniconfig==2.0.0
    typing-extensions==4.10.0
    ");

    Ok(())
}

/// Frozen exports honor member-defined groups before inherited workspace-root groups.
#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_frozen_workspace_member_group_precedence() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    context
        .temp_dir
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "root"
            version = "0.1.0"
            requires-python = ">=3.12"

            [dependency-groups]
            dev = ["sniffio"]
            root-only = ["idna"]

            [tool.uv.workspace]
            members = ["child"]
        "#})?;

    context
        .temp_dir
        .child("child")
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "child"
            version = "0.1.0"
            requires-python = ">=3.12"
            dependencies = ["typing-extensions"]

            [dependency-groups]
            dev = ["iniconfig"]
        "#})?;

    context.lock().assert().success();

    uv_snapshot!(context.filters(), context.export()
        .arg("--frozen")
        .arg("--no-header")
        .arg("--no-hashes")
        .arg("--no-annotate")
        .arg("--package").arg("child"), @"
    exit_code: 0 (success)
    ----- stdout -----
    iniconfig==2.0.0
    typing-extensions==4.10.0
    ");

    uv_snapshot!(context.filters(), context.export()
        .arg("--frozen")
        .arg("--no-header")
        .arg("--no-hashes")
        .arg("--no-annotate")
        .arg("--package").arg("child")
        .arg("--group").arg("dev"), @"
    exit_code: 0 (success)
    ----- stdout -----
    iniconfig==2.0.0
    typing-extensions==4.10.0
    ");

    uv_snapshot!(context.filters(), context.export()
        .arg("--frozen")
        .arg("--no-header")
        .arg("--no-hashes")
        .arg("--no-annotate")
        .arg("--package").arg("child")
        .arg("--group").arg("root-only"), @"
    exit_code: 0 (success)
    ----- stdout -----
    idna==3.6
    iniconfig==2.0.0
    typing-extensions==4.10.0
    ");

    Ok(())
}

