/// `--no-emit-workspace` should be respected when `--all-packages` is passed,
/// even if the workspace has a single member (i.e., no additional packages).
///
/// See: <https://github.com/astral-sh/uv/issues/18070>
#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_no_emit_workspace_all_packages() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0"]

        [build-system]
        requires = ["uv_build>=0.8.22,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    // `--no-emit-workspace --all-packages` on a single-member workspace should not emit `-e .`.
    uv_snapshot!(context.filters(), context.export().arg("--no-emit-workspace").arg("--all-packages"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --no-emit-workspace --all-packages
    anyio==3.7.0 \
        --hash=sha256:c8f99c47f03aec932b6cee4178beb10ce5b0aaf6d3e1ff52cc5e49fc3186af0a \
        --hash=sha256:ea75fecadcfa9b11a8bfa2ff25ea52a2904950d4925ba758c97d97e32c314556
        # via project
    idna==3.6 \
        --hash=sha256:9aae8f72192b28db0d56fcef130afe490d1538a8d1bf1700e6d219521421525f \
        --hash=sha256:e80025850eafa8760055fd6f2f6e83f84bf13d4a844fe81abb2b499e3a3e8af0
        # via anyio
    sniffio==1.3.1 \
        --hash=sha256:2743fa2a853c508a2310882c0b4104631e0b0fcb855e00a912b7e3f27e6b3f05 \
        --hash=sha256:ce520d2eb3c2be02f0c148dab5ba304e8705e1c7e7b4bec8a9146c464a597a6a
        # via anyio

    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    Ok(())
}

