#[cfg(feature = "test-universal")]
#[test]
fn requirements_txt_conflicts() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["iniconfig==1.1.1"]

        [tool.uv]
        conflicts = [
            [
              { extra = "extra1" },
              { extra = "extra2" },
            ],
        ]

        [project.optional-dependencies]
        extra1 = ["sortedcontainers==2.3.0"]
        extra2 = ["sortedcontainers==2.4.0"]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    context.lock().assert().success();

    uv_snapshot!(context.filters(), context.export(), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR]
    -e .
    iniconfig==1.1.1 \
        --hash=sha256:4f511134392ee75a8077a69be0d19cd4e5abb3a99ca54c7ab4a8e09ba0bc6991 \
        --hash=sha256:7832a237a8357e11d0a6e6a909bff9806c6f378393862998cd328fcf9d54d509
        # via project

    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.export().arg("--extra").arg("extra1"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --extra extra1
    -e .
    iniconfig==1.1.1 \
        --hash=sha256:4f511134392ee75a8077a69be0d19cd4e5abb3a99ca54c7ab4a8e09ba0bc6991 \
        --hash=sha256:7832a237a8357e11d0a6e6a909bff9806c6f378393862998cd328fcf9d54d509
        # via project
    sortedcontainers==2.3.0 \
        --hash=sha256:3228c480e84b2b7a504f28bd68f73b8cfde1d1fddf8a47783b19a0dbcc93ffcf \
        --hash=sha256:c7bfd220eb6dcc29774e2e05298edc2c5d62fa1086cc6409c800c7f413afe2a6
        # via project

    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.export().arg("--extra").arg("extra2"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --extra extra2
    -e .
    iniconfig==1.1.1 \
        --hash=sha256:4f511134392ee75a8077a69be0d19cd4e5abb3a99ca54c7ab4a8e09ba0bc6991 \
        --hash=sha256:7832a237a8357e11d0a6e6a909bff9806c6f378393862998cd328fcf9d54d509
        # via project
    sortedcontainers==2.4.0 \
        --hash=sha256:e90c0f20bb5c630bbf840e4ccc94441cd55ae8048cf55fc42df715d28b67cb80 \
        --hash=sha256:fb6015d312cfaf15c65e0aeadac28191546cc25e48d41b126ecc322d5b116be2
        # via project

    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.export().arg("--extra").arg("extra1").arg("--extra").arg("extra2"), @"
    exit_code: 2 (failure)
    ----- stderr -----
    Resolved 4 packages in [TIME]
    error: Extras `extra1` and `extra2` are incompatible with the declared conflicts: {`project[extra1]`, `project[extra2]`}
    ");

    Ok(())
}

