/// Check that relative and absolute paths are preserved in pylock.toml export.
///
/// See: <https://github.com/astral-sh/uv/issues/16514>
#[cfg(feature = "test-universal")]
#[test]
fn pep_751_relative_and_absolute_paths() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc! {r#"
        [project]
        name = "a"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["b", "c"]

        [tool.uv.sources]
        b = {{ path = "b" }}
        c = {{ path = '{}' }}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
        context.temp_dir.join("c").display()
    })?;
    context.temp_dir.child("a/__init__.py").touch()?;
    context
        .temp_dir
        .child("b/pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "b"
        version = "0.1.0"
        dependencies = []
        requires-python = ">=3.12"
        license = {text = "MIT"}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;
    context.temp_dir.child("b/b/__init__.py").touch()?;
    context
        .temp_dir
        .child("c/pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "c"
        version = "0.1.0"
        dependencies = []
        requires-python = ">=3.12"
        license = {text = "MIT"}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;
    context.temp_dir.child("c/c/__init__.py").touch()?;

    context.lock().assert().success();

    uv_snapshot!(context.filters(), context.export().arg("--format").arg("pylock.toml"), @r#"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --format pylock.toml
    lock-version = "1.0"
    created-by = "uv"
    requires-python = ">=3.12"

    [[packages]]
    name = "a"
    directory = { path = ".", editable = true }

    [[packages]]
    name = "b"
    directory = { path = "b", editable = false }

    [[packages]]
    name = "c"
    directory = { path = "[TEMP_DIR]/c", editable = false }

    ----- stderr -----
    Resolved 3 packages in [TIME]
    "#);

    Ok(())
}

/// Support `UV_NO_EDITABLE=1 uv export`.
///
/// <https://github.com/astral-sh/uv/issues/15103>
#[cfg(feature = "test-universal")]
#[test]
fn no_editable_env_var() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    context
        .init()
        .arg("--lib")
        .arg("--name")
        .arg("project")
        .arg(".")
        .assert()
        .success();

    uv_snapshot!(context.filters(), context.export().env(EnvVars::UV_NO_EDITABLE, "1"), @"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR]
    .

    ----- stderr -----
    Resolved 1 package in [TIME]
    ");

    uv_snapshot!(context.filters(), context.export().arg("--editable").env(EnvVars::UV_NO_EDITABLE, "1"), @"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --editable
    -e .

    ----- stderr -----
    Resolved 1 package in [TIME]
    ");

    Ok(())
}

#[cfg(feature = "test-universal")]
#[test]
fn export_only_group_and_extra_conflict() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = []

        [project.optional-dependencies]
        test = ["pytest"]

        [dependency-groups]
        dev = ["ruff"]
        "#,
    )?;

    // Using --only-group and --extra together should error.
    uv_snapshot!(context.filters(), context.export().arg("--only-group").arg("dev").arg("--extra").arg("test"), @"
    exit_code: 2 (failure)
    ----- stderr -----
    error: the argument '--only-group <ONLY_GROUP>' cannot be used with '--extra <EXTRA>'

    Usage: uv export --cache-dir [CACHE_DIR] --only-group <ONLY_GROUP> --exclude-newer <EXCLUDE_NEWER>

    For more information, try '--help'.
    ");

    // Using --only-group and --all-extras together should also error.
    uv_snapshot!(context.filters(), context.export().arg("--only-group").arg("dev").arg("--all-extras"), @"
    exit_code: 2 (failure)
    ----- stderr -----
    error: the argument '--only-group <ONLY_GROUP>' cannot be used with '--all-extras'

    Usage: uv export --cache-dir [CACHE_DIR] --only-group <ONLY_GROUP> --exclude-newer <EXCLUDE_NEWER>

    For more information, try '--help'.
    ");

    Ok(())
}

/// The members in the workspace (`foo`) and in the lockfile (`bar`) mismatch.
#[cfg(feature = "test-universal")]
#[test]
fn export_lock_workspace_mismatch_with_frozen() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "foo"
        version = "0.1.0"
        requires-python = ">=3.12"
        "#,
    )?;

    let pyproject_toml = context.temp_dir.child("uv.lock");
    pyproject_toml.write_str(
        r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [[package]]
        name = "bar"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = []
        "#,
    )?;

    uv_snapshot!(context.filters(), context.export().arg("--frozen"), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: The lockfile at `uv.lock` needs to be updated, but `--frozen` was provided: Missing workspace member `foo`.

    hint: To update the lockfile, run `uv lock`.
    ");

    Ok(())
}

/// Export multiple packages within a workspace.
#[cfg(feature = "test-universal")]
#[test]
fn multiple_packages() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "root"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["foo", "bar", "baz"]

        [tool.uv.sources]
        foo = { workspace = true }
        bar = { workspace = true }
        baz = { workspace = true }

        [tool.uv.workspace]
        members = ["packages/*"]
        "#,
    )?;

    context
        .temp_dir
        .child("packages")
        .child("foo")
        .child("pyproject.toml")
        .write_str(
            r#"
        [project]
        name = "foo"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio"]
        "#,
        )?;

    context
        .temp_dir
        .child("packages")
        .child("bar")
        .child("pyproject.toml")
        .write_str(
            r#"
        [project]
        name = "bar"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["typing-extensions"]
        "#,
        )?;

    context
        .temp_dir
        .child("packages")
        .child("baz")
        .child("pyproject.toml")
        .write_str(
            r#"
        [project]
        name = "baz"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["iniconfig"]
        "#,
        )?;

    context.lock().assert().success();

    // Export `foo` and `bar`.
    uv_snapshot!(context.filters(), context.export()
        .arg("--package").arg("foo")
        .arg("--package").arg("bar"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --package foo --package bar
    -e ./packages/bar
    -e ./packages/foo
    anyio==4.3.0 \
        --hash=sha256:13a6d97fa30ec110d85e3949a30c92306f0178135048329f54a335c3dade753a \
        --hash=sha256:c4f443e7e5a2c003b1534688207e85dbd11960efb66d4d6a4e7693fdfc6f5b33
        # via foo
    idna==3.6 \
        --hash=sha256:9aae8f72192b28db0d56fcef130afe490d1538a8d1bf1700e6d219521421525f \
        --hash=sha256:e80025850eafa8760055fd6f2f6e83f84bf13d4a844fe81abb2b499e3a3e8af0
        # via anyio
    sniffio==1.3.1 \
        --hash=sha256:2743fa2a853c508a2310882c0b4104631e0b0fcb855e00a912b7e3f27e6b3f05 \
        --hash=sha256:ce520d2eb3c2be02f0c148dab5ba304e8705e1c7e7b4bec8a9146c464a597a6a
        # via anyio
    typing-extensions==4.10.0 \
        --hash=sha256:0626263fe1dcda7bc3ee7b2872064b534d4831718055d22d4f32f9e474a867a4 \
        --hash=sha256:adefbbc2f75a47edb1f4491a2e99a45438ec3dd0c2670276b321cad2ca522246
        # via bar

    ----- stderr -----
    Resolved 9 packages in [TIME]
    ");

    // Export `foo`, `bar`, and `baz`.
    uv_snapshot!(context.filters(), context.export()
        .arg("--package").arg("foo")
        .arg("--package").arg("bar")
        .arg("--package").arg("baz"), @r"
    exit_code: 0 (success)
    ----- stdout -----
    # This file was autogenerated by uv via the following command:
    #    uv export --cache-dir [CACHE_DIR] --package foo --package bar --package baz
    -e ./packages/bar
    -e ./packages/baz
    -e ./packages/foo
    anyio==4.3.0 \
        --hash=sha256:13a6d97fa30ec110d85e3949a30c92306f0178135048329f54a335c3dade753a \
        --hash=sha256:c4f443e7e5a2c003b1534688207e85dbd11960efb66d4d6a4e7693fdfc6f5b33
        # via foo
    idna==3.6 \
        --hash=sha256:9aae8f72192b28db0d56fcef130afe490d1538a8d1bf1700e6d219521421525f \
        --hash=sha256:e80025850eafa8760055fd6f2f6e83f84bf13d4a844fe81abb2b499e3a3e8af0
        # via anyio
    iniconfig==2.0.0 \
        --hash=sha256:48c42a08c0ec1a24f2fe45f4efdefc9c19ac8e0aa8e82284503ccba80398bec3 \
        --hash=sha256:8a0fc44e516906bdecc91af1c3bc12134c9d1647a482446edc62f2f72191416c
        # via baz
    sniffio==1.3.1 \
        --hash=sha256:2743fa2a853c508a2310882c0b4104631e0b0fcb855e00a912b7e3f27e6b3f05 \
        --hash=sha256:ce520d2eb3c2be02f0c148dab5ba304e8705e1c7e7b4bec8a9146c464a597a6a
        # via anyio
    typing-extensions==4.10.0 \
        --hash=sha256:0626263fe1dcda7bc3ee7b2872064b534d4831718055d22d4f32f9e474a867a4 \
        --hash=sha256:adefbbc2f75a47edb1f4491a2e99a45438ec3dd0c2670276b321cad2ca522246
        # via bar

    ----- stderr -----
    Resolved 9 packages in [TIME]
    ");

    Ok(())
}

